LEGACY_RECORDS = [{'source': 'benchmark_dataset/Variant25/inputs/batch_01/export_01.csv', 'values': {'worker_id': 'W12', 'skill': 'Junior', 'on_leave': '0'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_01/export_01.csv', 'values': {'worker_id': 'W06', 'skill': 'Expert', 'on_leave': '0'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_01/export_01.csv', 'values': {'worker_id': 'W04', 'skill': 'Intermediate', 'on_leave': '0'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_01/export_01.csv', 'values': {'worker_id': 'W01', 'skill': 'Junior', 'on_leave': '1'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_01/export_01.csv', 'values': {'worker_id': 'W11', 'skill': 'Junior', 'on_leave': '0'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_01/export_01.csv', 'values': {'worker_id': 'W10', 'skill': 'Intermediate', 'on_leave': '0'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_01/export_01.csv', 'values': {'worker_id': 'W02', 'skill': 'Intermediate', 'on_leave': '0'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_01/export_01.csv', 'values': {'worker_id': 'W00', 'skill': 'Expert', 'on_leave': '0'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_02/export_02.csv', 'values': {'project_id': 'P00', 'required_skill': 'Junior'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_02/export_02.csv', 'values': {'project_id': 'P01', 'required_skill': 'Junior'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_02/export_02.csv', 'values': {'project_id': 'P02', 'required_skill': 'Junior'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_02/export_02.csv', 'values': {'project_id': 'P03', 'required_skill': 'Junior'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_02/export_02.csv', 'values': {'project_id': 'P04', 'required_skill': 'Junior'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_02/export_02.csv', 'values': {'project_id': 'P05', 'required_skill': 'Intermediate'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_03/export_03.csv', 'values': {'worker_id': 'W11', 'P00': '1091', 'P01': '324', 'P02': '379', 'P03': '272', 'P04': '', 'P05': ''}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_03/export_03.csv', 'values': {'worker_id': 'W10', 'P00': '1176', 'P01': '1111', 'P02': '1380', 'P03': '542', 'P04': '158', 'P05': '922'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_03/export_03.csv', 'values': {'worker_id': 'W06', 'P00': '', 'P01': '822', 'P02': '', 'P03': '223', 'P04': '1155', 'P05': '1055'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_03/export_03.csv', 'values': {'worker_id': 'W01', 'P00': '5', 'P01': '', 'P02': '20', 'P03': '', 'P04': '18', 'P05': '7'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_03/export_03.csv', 'values': {'worker_id': 'W02', 'P00': '', 'P01': '1397', 'P02': '953', 'P03': '714', 'P04': '205', 'P05': ''}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_03/export_03.csv', 'values': {'worker_id': 'W00', 'P00': '1063', 'P01': '219', 'P02': '', 'P03': '1329', 'P04': '', 'P05': '436'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_03/export_03.csv', 'values': {'worker_id': 'W04', 'P00': '642', 'P01': '', 'P02': '1130', 'P03': '133', 'P04': '199', 'P05': '311'}}, {'source': 'benchmark_dataset/Variant25/inputs/batch_03/export_03.csv', 'values': {'worker_id': 'W12', 'P00': '102', 'P01': '353', 'P02': '651', 'P03': '102', 'P04': '', 'P05': '7'}}]
import gurobipy as gp
from gurobipy import GRB
workers = []
worker_skill = {}
worker_on_leave = {}
projects = []
project_required_skill = {}
cost = {}
eligibility_mask = {}
skill_level_map = {'Junior': 1, 'Intermediate': 2, 'Senior': 3, 'Expert': 4}
for rec in LEGACY_RECORDS:
    vals = rec['values']
    if 'worker_id' in vals and 'skill' in vals:
        wid = vals['worker_id']
        workers.append(wid)
        worker_skill[wid] = vals['skill']
        worker_on_leave[wid] = int(vals['on_leave'])
    if 'project_id' in vals and 'required_skill' in vals:
        pid = vals['project_id']
        projects.append(pid)
        project_required_skill[pid] = vals['required_skill']
workers = [w for w in workers if worker_on_leave[w] == 0]
projects = list(dict.fromkeys(projects))
cost = {w: {} for w in workers}
eligibility_mask = {w: {} for w in workers}
for rec in LEGACY_RECORDS:
    vals = rec['values']
    if 'worker_id' in vals and any((p in vals for p in projects)):
        wid = vals['worker_id']
        if wid not in workers:
            continue
        for pid in projects:
            v = vals.get(pid, None)
            if v is not None and v != '':
                cost[wid][pid] = int(v)
            else:
                cost[wid][pid] = None
for w in workers:
    w_skill_level = skill_level_map[worker_skill[w]]
    for p in projects:
        p_skill_level = skill_level_map[project_required_skill[p]]
        eligible = worker_on_leave[w] == 0 and w_skill_level >= p_skill_level and (cost[w][p] is not None)
        eligibility_mask[w][p] = 1 if eligible else 0
for w in workers:
    for p in projects:
        if eligibility_mask[w][p]:
            if cost[w][p] is None:
                raise ValueError(f'Missing cost for eligible pair ({w},{p})')
eligible_pairs = [(w, p) for w in workers for p in projects if eligibility_mask[w][p]]
m = gp.Model('AP_Variant25')
x_vars = m.addVars(eligible_pairs, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((cost[w][p] * x_vars[w, p] for (w, p) in eligible_pairs)), GRB.MINIMIZE)
for p in projects:
    m.addConstr(gp.quicksum((x_vars[w, p] for w in workers if eligibility_mask[w][p])) == 1, name=f'project_{p}')
for w in workers:
    m.addConstr(gp.quicksum((x_vars[w, p] for p in projects if eligibility_mask[w][p])) <= 1, name=f'worker_{w}')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in x_vars.values():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')